/*
	Connecting Circuits - 🧰 Iterations 22.02.2024
	https://openprocessing.org/sketch/2186056
	#creativecoding #generativeart #p5js #WCCChallenge

	Dear Raph and creative coding community,

	made an iteration of a BirdsNest Streaming Background submission.
	Iterating over a grid to connect the point.
	Added also horizontal and vertical connections.
	Iterating thru different pallettes for each cell thru a noise field,
	to avoid harsh palette changes.

	Iterated over the word iterations as much as posible now :D

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

// const S = 600;
var C = 20; // cell size
var F = 300; // frame count before palette change
var palettes = ([
	["#ff2a6d", "#d1f7ff", "#f5d9e8", "#005678", "#01012b"],
	["#b0acb0", "#e2dddf", "#85ebd9", "#3d898d", "#2f404d"],
	["#ff6e27", "#fbf665", "#73fffe", "#6287f8", "#383e65"],
	["#7700a6", "#fe00fe", "#defe47", "#00b3fe", "#0016ee"],
	["#ff184c", "#ff577d", "#ffccdc", "#0a9cf5", "#003062"]
]).map((p) => p.map((e) => e + "A0"));
var pIdx = 0;

function setup() {
  createCanvas(innerWidth, innerHeight);
	frameRate(60)
	describe("animation of randomly connecting circuits over time switching thru different palettes ");
	pIdx = (pIdx + 1) % palettes.length;
  frameRate(30);
  loop();
}

function draw() {
	if (frameCount % 300 === 0) setup(); // 5 sec
  const S = max(width, height)
  const D = S / C;

	// background("lightgray");
	background(222, 32)
	background(32)

	// translate((noise(12.3+frameCount*0.0234)-0.5)*D*2, (noise(23.1+frameCount*0.0341)-0.5)*D*2)
  strokeWeight(D / 2);
  for (y = D; y < height; y += D) {
    for (x = D; x < width; x += D) {
      stroke(arr_noise(pIdx, x*x-y));
      point(x, y);
			const n = noise(252345.23 + frameCount * 0.00142 + x + y * 1.34);
			const xf = noise(245.231 + frameCount * 0.0008142 + x + y * 1.34) < 0.5 ? -1 : 1;
			const yf = noise(1345.123 + frameCount * 0.0009142 + x * 1.34 + y) < 0.5 ? -1 : 1;
			if (n < 0.1) {
				// low prob horizontal line
        stroke(arr_noise(pIdx, x+y*y));
        mline(x, y, x + xf * D, y);
      } else if (n < 0.2) {
				// low prob vertical line
        stroke(arr_noise(pIdx, x+y*y));
        mline(x, y, x, y + yf * D);
      } else if (n < 0.4) {
				// mid prob diagonal line
        stroke(arr_noise(pIdx, x+y*y));
        mline(x, y, x + xf * D, y + yf * D);
      }
    }
  }
}

// draw a line, when not outside the grid
function mline(x1, y1, x2, y2) {
  if (x1 === 0 || y1 === 0 || x2 === 0 || y2 === 0) return;
  if (x1 >= width || x2 >= width) return;
  if (y1 >= height || y2 >= height) return;
  line(x1, y1, x2, y2);
}

// gets a color, slightly iterating thru the palettes by comparing noise to current frame
function arr_noise(aIdx, magicNum) {
	const nIdx = (aIdx + 1) % palettes.length;
  var n = noise(magicNum + frameCount * 0.001234);
	const arr = palettes[(frameCount % F) / F < n ? aIdx : nIdx]
  const i = ~~(n * arr.length);
  return arr[i];
}

